using namespace std;

long long C(int n, int r, int mod, vector<vector<int>>& fif) {
    if (n < 0 || r < 0 || r > n) return 0;
    return (long long)fif[0][n] * fif[1][r] % mod * fif[1][n - r] % mod;
}

long long pow_mod(long long base, int exp, int mod) {
    long long result = 1;
    long long b = base % mod;
    for (int i = 0; i < exp; i++) {
        result = result * b % mod;
    }
    return result;
}

vector<vector<int>> enumFIF(int n, int mod) {
    vector<int> fact(n + 1);
    vector<int> invFact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; i++) {
        fact[i] = (int)((long long)fact[i - 1] * i % mod);
    }
    long long a = fact[n];
    long long b = mod;
    long long p = 1, q = 0;
    while (b > 0) {
        long long c = a / b;
        long long d = a;
        a = b;
        b = d % b;
        d = p;
        p = q;
        q = d - c * q;
    }
    invFact[n] = (int)(p < 0 ? p + mod : p);
    for (int i = n - 1; i >= 0; i--) {
        invFact[i] = (int)((long long)invFact[i + 1] * (i + 1) % mod);
    }
    return {fact, invFact};
}

int main() {
    ios::sync_with_stdio(false);
